// ===== AR Engine: Fetch, Kill-Switch, Decide, Render =====
// Mode: Run Once for All Items. Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false
// so the Code node can read the env vars listed in n8n/ARCHITECTURE.md.
const env = $env;
const CFG = {
  stripeKey: env.STRIPE_RESTRICTED_KEY,
  dryRun: String(env.DRY_RUN ?? 'true').toLowerCase() !== 'false',
  enabled: String(env.ENGINE_ENABLED ?? 'true').toLowerCase() !== 'false',
  minGap: Number(env.MIN_DAYS_BETWEEN_SENDS ?? 3),
  minAmount: Number(env.MIN_AMOUNT_CENTS ?? 100),
  excluded: String(env.EXCLUDED_CUSTOMERS ?? '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean),
  timezone: env.TIMEZONE || 'UTC',
  agencyName: env.AGENCY_NAME || 'Our Agency',
  signature: env.AGENCY_SIGNATURE || 'The Billing Team',
  billingEmail: env.REPLY_TO || env.FROM_EMAIL || 'billing@agency.com',
  interestRate: env.LATE_INTEREST_RATE || '1.5% per month',
  msaClause: env.MSA_LATE_CLAUSE || 'Section 6 (Payment Terms)',
};
if (!CFG.enabled) return [];
if (!CFG.stripeKey || CFG.stripeKey.startsWith('sk_')) throw new Error('Set STRIPE_RESTRICTED_KEY to a restricted rk_ key.');

const TEMPLATES = {
  "1": {
    "subject": "Friendly heads-up: invoice {{invoice_number}} is due {{due_date}}",
    "body": "Hi {{client_name}},\n\nA quick, friendly heads-up from the {{agency_name}} billing desk: invoice **{{invoice_number}}** for **{{amount}}** is due on **{{due_date}}**.\n\nIf it's already scheduled on your side, thank you — there's nothing more to do. If it's easier to take care of now, you can pay securely by card or bank transfer in under a minute:\n\n[View and pay invoice {{invoice_number}}]({{payment_link}})\n\nNeed a PO number added, a different billing contact, or a copy sent to your accounts team? Just reply to this email and we'll sort it out the same day.\n\nThanks for being a great partner,\n{{signature}}\n{{agency_name}} · {{billing_email}}"
  },
  "2": {
    "subject": "Invoice {{invoice_number}} is due today — {{amount}}",
    "body": "Hi {{client_name}},\n\nThis is an automated notice that invoice **{{invoice_number}}** is due today.\n\n- Invoice: {{invoice_number}}\n- Amount due: {{amount}}\n- Due date: {{due_date}}\n- Pay online: [Secure payment page]({{payment_link}})\n\nIf payment has already been sent, please disregard this message — our records update automatically once funds are received.\n\nFor remittance details or a W-9/tax form, reply to this email or contact {{billing_email}}.\n\nRegards,\n{{signature}}\n{{agency_name}}"
  },
  "3": {
    "subject": "Checking in on invoice {{invoice_number}}",
    "body": "Hi {{client_name}},\n\nWe haven't yet received payment for invoice **{{invoice_number}}** ({{amount}}), which was due on **{{due_date}}** — now {{days_overdue}} days ago.\n\nThese things usually come down to a simple admin snag: the invoice landed in the wrong inbox, it's waiting on an approval, or your AP team needs a vendor form from us. If any of those apply, reply with what you need and we'll turn it around today.\n\nIf it's ready to go, here's the direct payment link:\n\n[Pay invoice {{invoice_number}}]({{payment_link}})\n\nCould you let us know an expected payment date either way? That helps us keep your account in good standing and your project on schedule.\n\nThank you,\n{{signature}}\n{{agency_name}} · {{billing_email}}"
  },
  "4": {
    "subject": "Action required: work on your account pauses until invoice {{invoice_number}} is settled",
    "body": "Hi {{client_name}},\n\nInvoice **{{invoice_number}}** for **{{amount}}** is now **{{days_overdue}} days past due** (due {{due_date}}), and we haven't received payment or an expected payment date.\n\nTo keep things fair for every client we work with, our standard policy applies from this point:\n\n- Delivery of active project files and deliverables is temporarily paused.\n- Scheduled meetings and working sessions are placed on hold.\n- Work already in progress is preserved and resumes as soon as the balance clears.\n\nThis is a business boundary, not a judgment — we value the work we're doing together and want to get straight back to it. Settling the balance today restores everything immediately:\n\n[Pay {{amount}} now]({{payment_link}})\n\nIf there's a dispute or a cash-flow issue, reply to this email today. We're glad to discuss a short payment plan, but we need to hear from you to keep the project moving.\n\nRegards,\n{{signature}}\n{{agency_name}} · {{billing_email}}"
  },
  "5": {
    "subject": "FINAL NOTICE: invoice {{invoice_number}} — {{amount}} past due, late-payment interest applies",
    "body": "Dear {{client_name}},\n\nThis is a formal final notice regarding invoice **{{invoice_number}}**, issued by {{agency_name}}.\n\n- Outstanding balance: {{amount}}\n- Original due date: {{due_date}}\n- Days past due: {{days_overdue}}\n\nUnder the late-payment terms in our Master Services Agreement ({{msa_clause}}), overdue balances accrue interest at **{{interest_rate}}**, or the maximum rate permitted by applicable law if lower, together with any statutory interest and reasonable recovery costs to which we are entitled. We reserve the right to apply these charges from the original due date.\n\nPlease pay the outstanding balance in full within **7 days** of the date of this notice:\n\n[Pay invoice {{invoice_number}}]({{payment_link}})\n\nIf full payment or a written, agreed payment plan is not received within that period, the account will be referred for formal collection and we may pursue all remedies available under the agreement and applicable law, without further notice.\n\nIf you believe this notice is in error, or payment has already been made, reply to {{billing_email}} immediately with the remittance details.\n\nSincerely,\n{{signature}}\n{{agency_name}}"
  }
};
const LADDER = [[1, -3], [2, 0], [3, 3], [4, 7], [5, 14]];
const ledger = $getWorkflowStaticData('global');           // { sent: { invoiceId: {stage, at} } }
ledger.sent = ledger.sent || {};

const sleep = ms => new Promise(r => setTimeout(r, ms));
const stripeGet = async (path, qs = {}) => {
  for (let attempt = 0; attempt < 6; attempt++) {
    try {
      return await this.helpers.httpRequest({
        method: 'GET', url: `https://api.stripe.com${path}`, qs, json: true,
        headers: { Authorization: `Bearer ${CFG.stripeKey}` },
      });
    } catch (e) {
      const code = e.httpCode || e.statusCode || e.response?.status;
      if (![429, 500, 502, 503, 504].includes(Number(code)) || attempt === 5) throw e;
      await sleep(Math.min(60000, 1000 * 2 ** attempt) + Math.random() * 1000);
    }
  }
};

// Calendar date in the agency's timezone (YYYY-MM-DD -> day number).
const dayNumber = (d) => {
  const s = new Intl.DateTimeFormat('en-CA', { timeZone: CFG.timezone }).format(d);
  return Math.floor(Date.parse(s + 'T00:00:00Z') / 86400000);
};
const today = dayNumber(new Date());
const money = (cents, cur) => new Intl.NumberFormat('en-US', { style: 'currency', currency: cur.toUpperCase() })
  .format(['jpy', 'krw', 'vnd', 'clp', 'isk', 'ugx', 'xaf', 'xof', 'pyg', 'rwf'].includes(cur) ? cents : cents / 100);
const fmtDate = (unix) => new Intl.DateTimeFormat('en-US', { timeZone: CFG.timezone, month: 'long', day: 'numeric', year: 'numeric' }).format(new Date(unix * 1000));
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const render = (t, v) => t.replace(/{{\s*([a-z_]+)\s*}}/g, (_, k) => { if (!(k in v)) throw new Error('Unknown tag ' + k); return v[k]; });
const inline = s => esc(s).replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '<a href="$2" style="color:#0b5cff">$1</a>').replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
const toHtml = md => '<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1f2328;max-width:600px">' +
  md.trim().split(/\n\s*\n/).map(b => { const l = b.split('\n'); return l.every(x => /^\s*[-*] /.test(x)) ? '<ul>' + l.map(x => `<li>${inline(x.replace(/^\s*[-*] /, ''))}</li>`).join('') + '</ul>' : '<p>' + l.map(inline).join('<br>') + '</p>'; }).join('') + '</div>';
const toText = md => md.replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2').replace(/\*\*/g, '');

const killReason = inv => (inv.paid === true || inv.status === 'paid') ? 'paid'
  : inv.status !== 'open' ? `status=${inv.status}` : inv.amount_remaining <= 0 ? 'nothing remaining' : null;

function decide(dpd, last, daysSince) {
  let target = 0;
  for (const [n, off] of LADDER) if (dpd >= off) target = n;
  if (target <= last) return 0;
  if (target >= 4) target = Math.min(target, Math.max(last + 1, 3));
  if (last > 0 && daysSince !== null && daysSince < CFG.minGap) return 0;
  return target;
}

// ---- 1. Paginate GET /v1/invoices?status=open
const invoices = [];
let startingAfter;
do {
  const qs = { status: 'open', limit: 100, 'expand[]': 'data.customer' };
  if (startingAfter) qs.starting_after = startingAfter;
  const page = await stripeGet('/v1/invoices', qs);
  invoices.push(...page.data);
  startingAfter = page.has_more ? page.data[page.data.length - 1].id : undefined;
} while (startingAfter);

// ---- 2. Evaluate each invoice
const out = [];
for (let inv of invoices) {
  const cust = typeof inv.customer === 'object' && inv.customer ? inv.customer : {};
  const email = (inv.customer_email || cust.email || '').trim();
  const custId = typeof inv.customer === 'string' ? inv.customer : (cust.id || '');
  const vip = String(inv.metadata?.ar_engine_exclude || cust.metadata?.ar_engine_exclude || '').toLowerCase() === 'true'
    || CFG.excluded.includes(custId.toLowerCase()) || CFG.excluded.includes(email.toLowerCase());
  if (killReason(inv) || !inv.due_date || !email || !inv.hosted_invoice_url || vip || inv.amount_remaining < CFG.minAmount) continue;

  const dpd = today - dayNumber(new Date(inv.due_date * 1000));
  const prev = ledger.sent[inv.id];
  const daysSince = prev ? today - dayNumber(new Date(prev.at)) : null;
  const stage = decide(dpd, prev ? prev.stage : 0, daysSince);
  if (!stage) continue;

  if (!CFG.dryRun) {                        // kill-switch: live re-check right before sending
    inv = await stripeGet(`/v1/invoices/${inv.id}`);
    if (killReason(inv)) continue;
  }
  const v = {
    client_name: inv.customer_name || cust.name || 'there',
    invoice_number: inv.number || inv.id,
    amount: money(inv.amount_remaining, inv.currency),
    original_amount: money(inv.amount_due, inv.currency),
    amount_paid: money(inv.amount_paid, inv.currency),
    due_date: fmtDate(inv.due_date),
    payment_link: inv.hosted_invoice_url,
    days_overdue: Math.max(dpd, 0),
    agency_name: CFG.agencyName, signature: CFG.signature, billing_email: CFG.billingEmail,
    interest_rate: CFG.interestRate, msa_clause: CFG.msaClause,
  };
  const body = render(TEMPLATES[stage].body, v);
  out.push({ json: {
    dry_run: CFG.dryRun, invoice_id: inv.id, invoice_number: v.invoice_number, stage,
    days_past_due: dpd, to: email, subject: render(TEMPLATES[stage].subject, v),
    text: toText(body), html: toHtml(body), idempotency_key: `ar-${inv.id}-stage-${stage}`,
  }});
}
return out;

// ===== Record successful send in the dedup ledger (Run Once for Each Item) =====
const ledger = $getWorkflowStaticData('global');
ledger.sent = ledger.sent || {};
const src = $('Fetch & Decide').item.json;
const prev = ledger.sent[src.invoice_id];
if (!prev || src.stage > prev.stage) {
  ledger.sent[src.invoice_id] = { stage: src.stage, at: new Date().toISOString(), msg: $json.id || '' };
}
return { json: { ...src, html: undefined, text: undefined, provider_msg_id: $json.id || '', recorded: true } };
